let rows=[],filter='all';const list=document.getElementById('list');
function render(){list.replaceChildren();const visible=rows.filter(n=>filter==='all'||!n.read);document.getElementById('empty').hidden=visible.length>0;visible.forEach(n=>{const card=document.createElement('article');card.className='tile';const h=document.createElement('h2');h.textContent=n.title;const p=document.createElement('p');p.textContent=n.body;const meta=document.createElement('p');meta.className='eyebrow';meta.textContent=({'downloads':'Downloads','master-control':'Master Control','omni':'Omni'}[n.app]||'App')+(n.read?' · Read':' · New');const b=document.createElement('button');b.textContent='Dismiss';b.onclick=async()=>{b.disabled=true;try{await OmniUI.request('notifications.dismiss',{id:n.id});rows=Notices.dismiss(rows,n.id);render();OmniUI.focus(OmniUI.items()[0])}catch(_){OmniUI.notify('Could not dismiss. Try again.');b.disabled=false}};card.append(meta,h,p,b);list.append(card)});}
async function load(){try{rows=Notices.normalize(await OmniUI.request('notifications.list',{}),Date.now());render();OmniUI.notify('')}catch(_){OmniUI.notify('Notifications are unavailable.');}}
document.getElementById('refresh').onclick=load;document.getElementById('filter').onclick=()=>{filter=filter==='all'?'new':'all';document.getElementById('filter').textContent=filter==='all'?'Show new':'Show all';render()};load();

